import { View, Text, TextInput, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [form, setForm] = useState({ name: "", phone: "" });
  return (
    <View style={styles.screen}>
      <TextInput nativeID="name" style={styles.input} placeholder="Нэр"
        value={form.name} onChangeText={(v) => setForm({ ...form, name: v })} />
      <TextInput nativeID="phone" style={styles.input} placeholder="Утас" keyboardType="numeric"
        value={form.phone} onChangeText={(v) => setForm({ ...form, phone: v })} />
      <Pressable nativeID="clear" style={styles.btn}>
        {/* энд бичнэ үү: дархад бүх талбарыг хоослох onPress нэм */}
        <Text style={styles.btnText}>Цэвэрлэх</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  btn: { backgroundColor: "#ef4444", padding: 14, borderRadius: 10, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, TextInput, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [form, setForm] = useState({ name: "", phone: "" });
  return (
    <View style={styles.screen}>
      <TextInput nativeID="name" style={styles.input} placeholder="Нэр"
        value={form.name} onChangeText={(v) => setForm({ ...form, name: v })} />
      <TextInput nativeID="phone" style={styles.input} placeholder="Утас" keyboardType="numeric"
        value={form.phone} onChangeText={(v) => setForm({ ...form, phone: v })} />
      <Pressable nativeID="clear" style={styles.btn} onPress={() => setForm({ name: "", phone: "" })}>
        <Text style={styles.btnText}>Цэвэрлэх</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  btn: { backgroundColor: "#ef4444", padding: 14, borderRadius: 10, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
